"""RoboPaint trajectory driver. Uses only public RGB/depth and proprioception."""
import sys,json,time
from pathlib import Path
import numpy as np
from PIL import Image
sys.path.insert(0,'/opt/tools')
from rcb_client import Robot
ROOT=Path('/app/output')
Q=[0.,1.,0.,0.]
PAPER_Z=.02020
SCALE=.227185/1024
class Painter:
 def __init__(self):
  self.r=Robot(); self.o=self.r.get_obs(cameras=[],video='none');self.pose=np.array(self.o.meta['proprio']['now'][7:14]); self.seq=len(list(ROOT.glob('call_*.json')))
 def send(self,poses,note=''):
  poses=np.asarray(poses)
  for start in range(0,len(poses),180):
   a=poses[start:start+180];self.seq+=1
   f=ROOT/f'call_{self.seq:04d}'
   f.with_suffix('.json').write_text(json.dumps({'poses':a.tolist(),'dt':.05,'note':note}))
   res=self.r.submit('ee_pose',a,dt=.05,cameras=[],video='none',note=note)
   f.with_suffix('.meta.json').write_text(json.dumps(res.meta));self.pose=np.array(res.meta['proprio']['now'][7:14]);
   print(note, self.seq, 'tip',self.pose[:3], 'plan',res.meta.get('plan'),flush=True)
 def move(self,xyz,speed=.05,hold=.3):
  end=np.r_[xyz,Q];n=max(1,int(np.ceil(np.linalg.norm(end[:3]-self.pose[:3])/speed/.05)))
  a=np.linspace(self.pose,end,n+1)[1:]; a=np.vstack([a,np.tile(end,(round(hold/.05),1))]);self.send(a,'move')
 def observe(self,name):
  o=self.r.get_obs(cameras=['canvas_cam','practice_cam','scene_cam','side_cam'],depth=True);o.save(str(ROOT/name))
  for c,img in o.last.items():Image.fromarray(img).save(ROOT/f'{name}_{c}.png')
  print('status',self.r.status(),flush=True)
 def park(self):
  self.move([*self.pose[:2],.075]);self.move([-.10,-.29,.075]);
if __name__=='__main__':
 p=Painter()
 if sys.argv[1]=='clear':p.park();p.observe('clear')
